import { createHash } from 'node:crypto'
import { readFile } from 'node:fs/promises'
import { join } from 'node:path'
import { mechanicCatalog, damageRule } from './tower-mechanics-catalog.mjs'

export const sourceHash = (source) => createHash('sha256').update(source.replace(/\r\n/g, '\n')).digest('hex')

// Review fingerprints are deliberately NOT regenerated by sync:dove. A changed
// implementation must be read again before its prose can be called verified.
export async function loadMechanicReview(gameDir) {
  const review = JSON.parse(await readFile(new URL('./tower-mechanics-review.json', import.meta.url), 'utf8'))
  const files = new Map(await Promise.all(Object.entries(review.files).map(async ([file, hash]) => {
    try {
      const text = (await readFile(join(gameDir, file), 'utf8')).replace(/\r\n/g, '\n')
      return [file, { text, valid: sourceHash(text) === hash }]
    } catch { return [file, { text: '', valid: false }] }
  })))
  return { version: review.version, files }
}

export function buildTowerMechanics(rawTower, tower, review) {
  const definitions = [...(mechanicCatalog[rawTower.id] || [])]
  const common = damageRule(tower.attack.damageTypeValue ?? rawTower.template?.attacks?.list?.[0]?.damage_type)
  if (common) definitions.push(common)
  const items = []
  const pending = []
  for (const definition of definitions) {
    const sources = definition.sources.map(([file, anchor]) => {
      const source = review.files.get(file)
      const index = source?.text.indexOf(anchor) ?? -1
      return { file, symbol: anchor, line: index < 0 ? null : source.text.slice(0, index).split('\n').length, valid: Boolean(source?.valid && index >= 0) }
    })
    if (sources.some((source) => !source.valid)) {
      pending.push(definition.title)
      continue
    }
    items.push({ ...definition.build(rawTower), id: definition.id, title: definition.title, kind: definition.kind || 'intrinsic', sources: sources.map(({ valid, ...source }) => source) })
  }
  return { reviewedVersion: review.version, items, pending, hasSpecificReview: Boolean(mechanicCatalog[rawTower.id]) }
}
